select 'Prime Time Seniors — Grinchmas Craft','City-listed Prime Time Seniors crafting session to decorate a miniature holiday tree. November 18, 2026, 10 AM–noon at the TH-1 Room, 201 E Main Street. The City lists $5 for senior members and $8 for non-members and links registration. Check eligibility, remaining space and current terms through the official listing before booking. Checked November 6, 2026; event imagery not reused.','Mountain House','TH-1 Room, 201 E Main Street, Mountain House','2026-11-18T10:00:00-08:00'::timestamptz,'2026-11-18T12:00:00-08:00'::timestamptz,'Seasonal celebrations','https://www.mountainhouseca.gov/Calendar.aspx?EID=2556','HIGH','approved','editorial_seasonal_2026',1.0,false,'approved'
where not exists(select 1 from public.events where city='Mountain House' and source_url='https://www.mountainhouseca.gov/Calendar.aspx?EID=2556' and start_date='2026-11-18T10:00:00-08:00'::timestamptz);
insert into public.events(title,description,city,location,start_date,end_date,category,source_url,confidence,status,source,confidence_score,needs_review,ingestion_status)
